#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# ──────────────────────────────────────────────────────────────────────────
# STAGES — Hexagon SDK 6.6 + OpenCL SDK 2.3.2 for llama.cpp Hexagon NPU build.
# This wizard writes persistent Windows env vars (setx) and runs system
# actions — it does NOT use .env / GitHub secrets.
# ──────────────────────────────────────────────────────────────────────────

# require_dir PATH "what" — block until the human has extracted something to PATH.
require_dir() {
  local path="$1" what="$2"
  while [[ ! -d "$path" ]]; do
    warn "Not found yet: $path"
    say  "$what must be extracted to that exact path before we continue."
    if confirm "Skip this check and continue anyway (NOT recommended)?"; then return 0; fi
    pause "Extract it, then press Enter to re-check…"
  done
  printf '  %s✓ found%s %s\n' "$GREEN" "$RESET" "$path"
}

# setx_env KEY VALUE — persist a Windows user env var (survives new shells).
setx_env() {
  local key="$1" value="$2"
  if command -v setx >/dev/null 2>&1; then
    setx "$key" "$value" >/dev/null 2>&1 \
      && printf '  %s✓ set%s %s = %s %s(new shells)%s\n' "$GREEN" "$RESET" "$key" "$value" "$DIM" "$RESET" \
      || warn "setx failed for $key — set it by hand in System Properties → Environment Variables"
  else
    warn "setx not available — set $key=$value manually (System → Environment Variables)"
  fi
  export "$key"="$value"   # also live for the rest of THIS session
}

TOTAL_STAGES=7

banner "Hexagon NPU build prerequisites (llama.cpp ggml-hexagon)"

# ── Stage 1: OpenCL SDK download ──────────────────────────────────────────
stage "Adreno OpenCL SDK 2.3.2 — download"
say "The Adreno GPU half of the backend (GGML_OPENCL) needs the OpenCL SDK."
say "Log in to Qualcomm Software Center and download version 2.3.2."
open_url "https://softwarecenter.qualcomm.com/catalog/item/Adreno_OpenCL_SDK?version=2.3.2"
step "Sign in with your Qualcomm account and accept the license."
step "Download the 2.3.2 package (the Software Center desktop app uses the"
note "  system cert store, so it works where curl/winget fail behind Netskope)."
step "Extract its contents so the SDK lives exactly at:"
note "      C:\\Qualcomm\\OpenCL_SDK\\2.3.2"
pause "Press Enter once you've extracted it there…"
require_dir "C:/Qualcomm/OpenCL_SDK/2.3.2" "The OpenCL SDK 2.3.2"

# ── Stage 2: Hexagon SDK download ─────────────────────────────────────────
stage "Hexagon SDK Community Edition 6.6.0.0 — download"
warn "Download the SDK, NOT the 'Hexagon LLVM Tools' compiler-only package."
say "This is the full SDK (FastRPC/QuRT/rpcmem + a bundled compiler) the NPU"
say "skel build needs. The standalone Hexagon LLVM Tools you already have is"
say "not a substitute."
open_url "https://softwarecenter.qualcomm.com/catalog/item/Hexagon_SDK?version=6.6.0.0"
step "Sign in, accept the license, download Hexagon SDK 6.6.0.0 (Community Ed.)."
step "Extract its contents so the SDK lives exactly at:"
note "      C:\\Qualcomm\\Hexagon_SDK\\6.6.0.0"
note "  (It should contain tools\\HEXAGON_Tools\\19.0.07 inside.)"
pause "Press Enter once you've extracted it there…"
require_dir "C:/Qualcomm/Hexagon_SDK/6.6.0.0" "The Hexagon SDK 6.6.0.0"

# ── Stage 3: locate the bundled HEXAGON_Tools version ─────────────────────
stage "Confirm the bundled HEXAGON_Tools version"
say "The env vars below point at the compiler bundled INSIDE the Hexagon SDK."
say "Check the actual folder name (usually 19.0.07):"
if [[ -d "C:/Qualcomm/Hexagon_SDK/6.6.0.0/tools/HEXAGON_Tools" ]]; then
  step "Found these HEXAGON_Tools versions in the SDK:"
  ls "C:/Qualcomm/Hexagon_SDK/6.6.0.0/tools/HEXAGON_Tools" 2>/dev/null | sed 's/^/        /'
else
  warn "tools/HEXAGON_Tools not found under the SDK — check your extraction."
fi
ask HEX_TOOLS_VER "HEXAGON_Tools version folder to use [19.0.07]:"
[[ -z "$HEX_TOOLS_VER" ]] && HEX_TOOLS_VER="19.0.07"

# ── Stage 4: locate the Windows SDK bin ───────────────────────────────────
stage "Locate the Windows 10/11 SDK bin (for signing tools)"
say "Test-signing needs makecert / pvk2pfx from the Windows SDK/WDK."
if [[ -d "C:/Program Files (x86)/Windows Kits/10/bin" ]]; then
  step "Windows Kits bin versions available:"
  ls "C:/Program Files (x86)/Windows Kits/10/bin" 2>/dev/null | grep -E '^10\.' | sed 's/^/        /'
else
  warn "Windows Kits\\10\\bin not found — install the Windows SDK/WDK (comes with VS 2026)."
fi
ask WINSDK_VER "Windows SDK bin version to use [10.0.26100.0]:"
[[ -z "$WINSDK_VER" ]] && WINSDK_VER="10.0.26100.0"

# ── Stage 5: persist environment variables ────────────────────────────────
stage "Set environment variables (persistent)"
say "Writing these as Windows user env vars so every new shell sees them."
setx_env OPENCL_SDK_ROOT    "C:\\Qualcomm\\OpenCL_SDK\\2.3.2"
setx_env HEXAGON_SDK_ROOT   "C:\\Qualcomm\\Hexagon_SDK\\6.6.0.0"
setx_env HEXAGON_TOOLS_ROOT "C:\\Qualcomm\\Hexagon_SDK\\6.6.0.0\\tools\\HEXAGON_Tools\\$HEX_TOOLS_VER"
setx_env WINDOWS_SDK_BIN    "C:\\Program Files (x86)\\Windows Kits\\10\\bin\\$WINSDK_VER"
note "Open a NEW terminal after this wizard for the vars to take effect."

# ── Stage 6: enable test-signing (NPU only) ───────────────────────────────
stage "Enable Windows test-signing (required for the HTP/NPU skel)"
warn "This changes boot config and needs an Administrator shell + a reboot."
warn "Secure Boot may need to be disabled in UEFI for TESTSIGNING to stick."
say  "The Adreno GPU path does NOT need this — only the Hexagon NPU does."
if confirm "Show the command to run in an *Administrator* terminal now?"; then
  note "    bcdedit /set TESTSIGNING ON"
  note "  Then reboot. Verify after reboot with:  bcdedit /enum | findstr testsigning"
  step "Run it in an elevated PowerShell/cmd (this wizard is not elevated)."
fi
pause "Press Enter once test-signing is ON (or you've decided to do it later)…"

# ── Stage 7: create + import the HTP signing certificate ──────────────────
stage "Create & import the HTP signing certificate"
say "The NPU skel must be signed by a cert trusted on this machine."
CERT_DIR="C:\\Users\\$USERNAME\\Certs"
CERT_PFX="$CERT_DIR\\ggml-htp-v1.pfx"
say "We'll target: $CERT_PFX"
if confirm "Show the makecert/pvk2pfx + certlm import steps?"; then
  note "  In an Administrator 'Developer Command Prompt' (Windows SDK on PATH):"
  note "    mkdir \"$CERT_DIR\" 2>nul"
  note "    makecert -r -pe -n \"CN=ggml-htp\" -sv \"$CERT_DIR\\ggml-htp-v1.pvk\" \\"
  note "             \"$CERT_DIR\\ggml-htp-v1.cer\""
  note "    pvk2pfx -pvk \"$CERT_DIR\\ggml-htp-v1.pvk\" -spc \"$CERT_DIR\\ggml-htp-v1.cer\" \\"
  note "            -pfx \"$CERT_PFX\""
  step "Open certlm.msc (Local Machine cert store) and import ggml-htp-v1.cer into:"
  note "      • Trusted Root Certification Authorities → Certificates"
  note "      • Trusted Publishers → Certificates"
fi
pause "Press Enter once the .pfx exists and the cert is imported…"
setx_env HEXAGON_HTP_CERT "$CERT_PFX"

finish
say "Next: open a NEW terminal (so env vars load), then build llama.cpp:"
note "    git clone https://github.com/ggml-org/llama.cpp"
note "    cd llama.cpp"
note "    cmake --preset arm64-windows-snapdragon-release -B build-wos"
note "    cmake --install build-wos --prefix pkg-snapdragon"
note "Then copy pkg-snapdragon + the Q4_0 GGUF to PLAIN DISK (C:\\llm_hexagon), not Dropbox."
